def shifted_letters(s, shifts):
 total=0;answer=[]
 for char,shift in zip(reversed(s),reversed(shifts)):
  total=(total+shift)%26;answer.append(chr((ord(char)-97+total)%26+97))
 return ''.join(reversed(answer))

